export type PageViewEvent = {
  path: string
  referrer: string | null
  userAgent: string | null
  timestamp: string
}

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT

/**
 * Sends a page view to the analytics service.
 *
 * Never throws: analytics is best-effort, and this runs after the response has
 * already been sent, so a failure here must not surface as a request error.
 */
export async function logPageView(event: PageViewEvent): Promise<void> {
  if (!ANALYTICS_ENDPOINT) {
    console.log('[analytics] page_view', event)
    return
  }

  try {
    await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ type: 'page_view', ...event }),
      cache: 'no-store',
    })
  } catch (error) {
    console.error('[analytics] failed to log page view', error)
  }
}

