import { headers } from 'next/headers'
import { after } from 'next/server'

import { logPageView } from '@/lib/analytics'

export default async function Home() {
  // Read request data during render — `after` callbacks run once the response is
  // done, so capture what we need now and hand the values to the callback.
  const headerList = await headers()
  const event = {
    path: '/',
    referrer: headerList.get('referer'),
    userAgent: headerList.get('user-agent'),
    timestamp: new Date().toISOString(),
  }

  // Scheduled work: runs after the response is sent, so it never delays the page.
  after(() => logPageView(event))

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by.</p>
    </main>
  )
}

